import test from 'node:test'
import assert from 'node:assert/strict'
import { evaluate, preventEligible, validate } from '../src/features/lipidpath/engine.ts'
import { evidence, evidenceById } from '../src/features/lipidpath/evidence.ts'
import { nonHdl, ldlReduction, riskCategory, toMgDl } from '../src/features/lipidpath/calculations.ts'
// Expected clinical targets below are independently transcribed from the specified
// recommendation tables/figures, not generated by evaluating the implementation.
// Independent qualified clinical review remains pending.
const base={age:50,sex:'male',reproductive:'none',ascvd:false,diabetes:false,fh:'none',severeHistory:false,ckd:false,hiv:false,complexCare:false,safetyReviewed:true,ldl:120,statin:'none',risk10:4,risk30:15,riskConfirmed:true,smoking:false,strongFamilyHistory:false}
const result=(patch={})=>evaluate({...base,...patch})
const has=(r,id)=>r.considerations.some(c=>c.id===id)
const target=(r,n)=>assert.ok(r.goals.some(g=>g.ldl===n),JSON.stringify(r))
for(const [risk,expected] of [[0,'Low'],[2.999,'Low'],[3,'Borderline'],[3.001,'Borderline'],[4.999,'Borderline'],[5,'Intermediate'],[5.001,'Intermediate'],[9.999,'Intermediate'],[10,'High'],[10.001,'High'],[100,'High']])test(`primary risk boundary ${risk}: ${expected} (§4.2.3.2 R1)`,()=>{assert.equal(riskCategory(risk),expected);assert.equal(result({risk10:risk,risk30:undefined}).riskCategory,expected)})
for(const [name,patch,expected] of [
 ['borderline target',{risk10:3},100],['intermediate target',{risk10:5},100],['high target',{risk10:10},70],
 ['low long-term exception',{risk10:2,risk30:10},100],['low LDL exception',{risk10:2,risk30:5,ldl:160},100],
 ['severe uncomplicated',{severeHistory:true,baselineLdl:190,additionalRisks:false},100],
 ['severe plus risk',{severeHistory:true,baselineLdl:190,additionalRisks:true},70],
 ['severe plus HeFH',{severeHistory:true,baselineLdl:190,additionalRisks:false,fh:'hefh'},70],
 ['severe plus CAC',{severeHistory:true,baselineLdl:190,additionalRisks:false,cac:1,cacPercentile:10},70],
 ['severe plus ASCVD',{severeHistory:true,baselineLdl:190,ascvd:true,majorEvents:0,highRiskConditions:0},55],
 ['secondary not very high',{ascvd:true,majorEvents:1,highRiskConditions:1},70],
 ['secondary two events',{ascvd:true,majorEvents:2,highRiskConditions:0},55],
 ['secondary one and two',{ascvd:true,majorEvents:1,highRiskConditions:2},55],
 ['secondary no major events',{ascvd:true,majorEvents:0,highRiskConditions:7},70],
 ['diabetes',{diabetes:true,multipleDiabetesRisks:false},100],
 ['diabetes multiple risks',{diabetes:true,multipleDiabetesRisks:true},70],
 ['CKD plus ASCVD',{ckd:true,dialysis:false,egfr:45,ascvd:true,majorEvents:0,highRiskConditions:0},55],
])test(`${name}: source-defined LDL <${expected}`,()=>{const r=result(patch);assert.equal(r.status,'educational');target(r,expected);assert.ok(r.goals.some(g=>g.nonHdl===expected+30))})
for(const [score,percentile,expected] of [[1,0,100],[99,74.99,100],[1,75,70],[100,0,70],[299,0,70],[300,0,70],[999,0,70],[1000,0,55],[1001,0,55]])test(`CAC ${score}, percentile ${percentile}: §4.2.7`,()=>{const r=result({cac:score,cacPercentile:percentile});target(r,expected);assert.equal(r.riskCategory,undefined)})
test('CAC 1–99 cannot infer percentile below 75',()=>{const r=result({cac:99});assert.equal(r.goals.length,0);assert.match(r.missing.join(' '),/percentile/)})
for(const [sex,age,allowed] of [['male',39,false],['male',40,true],['female',44,false],['female',45,true]])test(`CAC age ${sex} ${age}`,()=>{const r=result({sex,age,cac:100});assert.equal(r.goals.length>0,allowed)})
test('CAC incidental mild and moderate-to-severe have distinct goals',()=>{target(result({incidentalCac:'mild'}),100);target(result({incidentalCac:'moderate-severe'}),70)})
test('CAC zero deferral requires preference and no exceptions',()=>{assert.ok(has(result({cac:0,avoidTherapy:true}),'cac-zero'));for(const patch of [{smoking:true},{strongFamilyHistory:true},{ckd:true,dialysis:false,egfr:50},{hiv:true,stableArt:true}])assert.ok(!has(result({cac:0,avoidTherapy:true,...patch}),'cac-zero'))})
test('CAC zero cannot override severe LDL, FH, diabetes or ASCVD',()=>{for(const patch of [{severeHistory:true,additionalRisks:false},{severeHistory:true,fh:'hefh',additionalRisks:false},{diabetes:true,multipleDiabetesRisks:false},{ascvd:true,majorEvents:2,highRiskConditions:0}]) {const r=result({cac:0,avoidTherapy:true,...patch});assert.ok(has(r,'cac-zero-exception'));assert.ok(!has(r,'cac-zero'))}})
for(const age of [29,30,79,80])test(`PREVENT eligibility age ${age}`,()=>assert.equal(preventEligible({...base,age}),age>=30&&age<=79))
for(const ldl of [69.99,70,189,190])test(`PREVENT eligibility LDL ${ldl}`,()=>assert.equal(preventEligible({...base,ldl}),ldl>=70&&ldl<190))
test('PREVENT excludes ASCVD, HeFH, CAC and severe history',()=>{for(const patch of [{ascvd:true},{fh:'hefh'},{cac:1},{incidentalCac:'mild'},{severeHistory:true}])assert.equal(preventEligible({...base,...patch}),false)})
test('unconfirmed / missing / inapplicable risk produces no fabricated category',()=>{for(const patch of [{riskConfirmed:false},{risk10:undefined},{age:29},{ldl:69},{ascvd:true,majorEvents:1,highRiskConditions:1}])assert.equal(result(patch).riskCategory,undefined)})
test('30-year risk requires age 30–59 and correct ordering',()=>{assert.ok(validate({...base,age:60,risk30:10}).length);assert.ok(validate({...base,risk10:10,risk30:9}).length)})
test('low-risk missing long-term result does not imply no treatment benefit',()=>{const r=result({risk10:2,risk30:undefined});assert.equal(r.goals.length,0);assert.match(r.missing.join(' '),/30-year/)})
for(const [name,patch] of [['pregnant',{reproductive:'pregnant'}],['planning',{reproductive:'planning'}],['lactating',{reproductive:'lactating'}],['child',{age:17,risk30:undefined}],['older',{age:80,risk30:undefined}],['HoFH',{fh:'hofh'}],['complex care',{complexCare:true}],['safety review declined',{safetyReviewed:false}],['dialysis',{ckd:true,dialysis:true,egfr:10}]])test(`scope stop: ${name}`,()=>{const r=result(patch);assert.equal(r.status,'review-required');assert.equal(r.goals.length,0);assert.equal(r.considerations.length,1)})
test('unknown essential data stops treatment output',()=>{for(const key of ['age','ascvd','diabetes','reproductive','severeHistory','ckd','hiv','complexCare','safetyReviewed','fh','ldl']){const r=result({[key]:undefined});assert.equal(r.status,'incomplete',key);assert.equal(r.goals.length,0);assert.ok(r.missing.length)}})
for(const [age,allowed] of [[39,false],[40,true],[75,true],[76,false]])test(`diabetes age ${age}`,()=>{const r=result({diabetes:true,multipleDiabetesRisks:false,age,risk30:undefined});assert.equal(r.goals.length>0,allowed)})
test('ASCVD unknown event counts must not be classified as lower risk',()=>{const r=result({ascvd:true});assert.equal(r.status,'incomplete');assert.equal(r.goals.length,0)})
test('CKD does not arise from a single low eGFR',()=>{assert.ok(!result({ckd:false,egfr:45}).pathways.includes('CKD primary prevention'));assert.ok(has(result({ckd:true,egfr:45,dialysis:false,risk10:undefined}),'ckd'))})
test('HIV eligibility needs stable combination ART',()=>{assert.ok(has(result({hiv:true,stableArt:true,risk10:undefined}),'hiv'));assert.equal(result({hiv:true,stableArt:undefined}).status,'review-required')})
for(const tg of [149.99,150,499,500,999,1000,1001])test(`TG threshold ${tg}: §4.2.9`,()=>{const r=result({tg,fasting:true,persistentTg:true,dietTrial:true,statin:'high',maxTolerated:true,adherent:true});assert.equal(r.safety.length>0,tg>=500);assert.equal(has(r,'tg-pancreatitis'),tg>=500);assert.equal(has(r,'tg-priority'),tg>=1000);assert.equal(has(r,'tg-apob'),tg>=150)})
test('nonfasting / unknown persistence does not trigger TG pharmacotherapy',()=>{for(const patch of [{fasting:false},{fasting:undefined},{persistentTg:undefined},{dietTrial:undefined}]){const r=result({tg:500,fasting:true,persistentTg:true,dietTrial:true,...patch});assert.ok(!has(r,'tg-pancreatitis'));assert.ok(r.safety.length)}})
test('FCS is referred without diagnosing it from TG',()=>{assert.equal(result({tg:1000,fcs:true}).status,'review-required');assert.ok(!has(result({tg:1000}),'fcs-review'))})
test('IPE needs age, persistent fasting TG, ASCVD/diabetes risk and maximally tolerated statin',()=>{const eligible={ascvd:true,majorEvents:1,highRiskConditions:0,ldl:80,tg:200,fasting:true,persistentTg:true,statin:'high',maxTolerated:true,adherent:true};assert.ok(has(result(eligible),'tg-ipe'));for(const patch of [{age:49},{fasting:false},{persistentTg:false},{ldl:100},{maxTolerated:false},{adherent:false}])assert.ok(!has(result({...eligible,...patch}),'tg-ipe'))})
for(const [unit,value,high] of [['mg/dL',49.99,false],['mg/dL',50,true],['mg/dL',50.01,true],['nmol/L',124.99,false],['nmol/L',125,true],['nmol/L',125.01,true]])test(`Lp(a) ${value} ${unit}`,()=>assert.equal(has(result({lpa:value,lpaUnit:unit}),'lpa'),high))
test('missing Lp(a) units block interpretation',()=>assert.ok(result({lpa:100}).errors.length))
test('apoB residual-risk assessment does not invent a goal',()=>{const r=result({apob:120});assert.ok(has(r,'apob'));assert.ok(r.goals.every(g=>!('apob' in g)))})
test('alternate severe phenotype cannot receive ordinary PREVENT goal',()=>{for(const patch of [{apob:141},{total:280,hdl:40}]){const r=result(patch);assert.equal(r.status,'review-required');assert.equal(r.goals.length,0);assert.ok(has(r,'severe-alternate'))}})
test('muscle symptoms do not diagnose intolerance or prescribe a change',()=>{const r=result({muscleSymptoms:true,severeMuscleSymptoms:true,statin:'high',maxTolerated:true,adherent:true});assert.ok(has(r,'muscle'));assert.ok(has(r,'muscle-discussion'));assert.ok(!has(r,'high-add'));assert.ok(r.safety.length)})
test('intensification requires confirmed maximum tolerated therapy and adherence',()=>{const active={ascvd:true,majorEvents:2,highRiskConditions:0,statin:'high',maxTolerated:true,adherent:true,ezetimibe:false,pcsk9:false,bempedoic:false,inclisiran:false};assert.ok(has(result(active),'very-high-add'));for(const patch of [{maxTolerated:undefined},{maxTolerated:false},{adherent:false},{ezetimibe:undefined}])assert.ok(!has(result({...active,...patch}),'very-high-add'))})
test('severe add-on carries only applicable recommendation evidence',()=>{const r=result({severeHistory:true,additionalRisks:false,statin:'high',maxTolerated:true,adherent:true,ezetimibe:false,pcsk9:false,bempedoic:false,inclisiran:false});assert.deepEqual(r.considerations.find(c=>c.id==='severe-add')?.evidence,['severe-simple'])})
for(const [key,value] of [['ldl',NaN],['tg',Infinity],['ldl',-1],['risk10',101],['age',50.5],['majorEvents',1.2],['statin','invalid'],['ascvd','false']])test(`invalid ${key} ${value} cannot yield clinical output`,()=>{const r=result({[key]:value});assert.ok(r.errors.length);assert.equal(r.goals.length,0)})
test('contradictory laboratories and history are rejected',()=>{for(const patch of [{total:100,hdl:110},{total:160,hdl:50,ldl:120},{majorEvents:1},{baselineLdl:190},{maxTolerated:true}])assert.ok(result(patch).errors.length)})
test('lab arithmetic: no fabricated baseline, negative change retained',()=>{assert.equal(nonHdl(200,50),150);assert.equal(nonHdl(30,50),undefined);assert.equal(nonHdl(undefined,50),undefined);assert.equal(ldlReduction(200,100),50);assert.equal(ldlReduction(undefined,100),undefined);assert.equal(ldlReduction(100,120),-20);assert.equal(ldlReduction(0,20),undefined);assert.ok(Math.abs(toMgDl(1,'cholesterol')-38.67)<0.01);assert.ok(Math.abs(toMgDl(1,'triglycerides')-88.57)<0.01);assert.throws(()=>toMgDl(-1,'cholesterol'))})
test('evidence registry and every emitted rule are traceable',()=>{assert.equal(new Set(evidence.map(e=>e.id)).size,evidence.length);for(const e of evidence){assert.ok(e.section&&e.recommendation&&e.page&&e.eligibility&&e.exceptions&&e.summary);assert.ok(e.sourceUrl.startsWith('https://doi.org/'))}for(const r of [result(),result({ascvd:true,majorEvents:2,highRiskConditions:0}),result({severeHistory:true,additionalRisks:false}),result({cac:1000}),result({tg:1000}),result({muscleSymptoms:true})])for(const item of [...r.considerations,...r.trace,...r.goals])for(const id of item.evidence)assert.ok(evidenceById[id],id)})
test('engine is deterministic and does not mutate input',()=>{const p=structuredClone(base),before=structuredClone(p);assert.deepEqual(evaluate(p),evaluate(p));assert.deepEqual(p,before)})
test('high primary-prevention add-on evidence and existing therapy are explicit',()=>{const p={risk10:10,statin:'high',maxTolerated:true,adherent:true,ezetimibe:false,pcsk9:false,bempedoic:false,inclisiran:false};assert.ok(has(result(p),'high-add'));assert.ok(has(result({...p,ezetimibe:true}),'high-add-next'));assert.ok(!has(result({...p,adherent:false}),'high-add'))})
test('inclisiran does not claim cardiovascular outcome benefit',()=>{const r=result({severeHistory:true,additionalRisks:false,statin:'high',maxTolerated:true,adherent:true,inclisiran:false,ezetimibe:false,pcsk9:false,bempedoic:false});assert.match(r.considerations.find(c=>c.id==='inclisiran').text,/outcomes trials were pending/);assert.ok(!has(result({severeHistory:true,additionalRisks:false,statin:'high',ldl:99,maxTolerated:true,adherent:true,inclisiran:false}),'inclisiran'))})
test('Lp(a) ASCVD add-on requires elevated result, unmet goals, no current PCSK9 and max statin',()=>{const p={ascvd:true,majorEvents:2,highRiskConditions:0,lpa:125,lpaUnit:'nmol/L',statin:'high',maxTolerated:true,adherent:true,pcsk9:false};assert.ok(has(result(p),'lpa-add'));for(const patch of [{lpa:124.9},{ldl:54},{maxTolerated:false},{pcsk9:true}])assert.ok(!has(result({...p,...patch}),'lpa-add'))})
test('CAC baseline already below goal uses the Figure 13 reduction caveat',()=>{const r=result({cac:300,baselineLdl:60,ldl:50});assert.equal(r.goals.find(g=>g.context==='CAC pathway').reduction,30);assert.ok(has(r,'cac-baseline'));assert.ok(has(r,'cac-optional'))})
test('review-required presentations suppress medication outputs across concurrent indications',()=>{const r=result({tg:1000,fcs:true,risk10:10,statin:'high',maxTolerated:true,adherent:true});assert.equal(r.status,'review-required');assert.equal(r.goals.length,0);assert.ok(!has(r,'high'));assert.equal(r.riskCategory,undefined)})
test('low-risk counseling and moderate-statin exception have distinct evidence grades',()=>{const general=result({risk10:2,risk30:5});assert.deepEqual(general.considerations.find(c=>c.id==='low-counseling').evidence,['lifestyle']);const exception=result({risk10:2,risk30:10});assert.deepEqual(exception.considerations.find(c=>c.id==='low').evidence,['low']);assert.equal(evidenceById.low.cor,'2a');assert.equal(evidenceById.low.loe,'C-LD')})
test('nonfasting TG 400 threshold prompts repeat fasting testing and defers LDL-based add-ons',()=>{const p={risk10:10,statin:'high',maxTolerated:true,adherent:true,ezetimibe:false,fasting:false};assert.ok(!has(result({...p,tg:399.99}),'fasting-repeat'));for(const tg of [400,400.01]){const r=result({...p,tg});assert.ok(has(r,'fasting-repeat'));assert.ok(!has(r,'high-add'))}})
